async function findRelevantSkills(taskDescription) {
  const skills = await discoverSkills();
  const relevant = [];
  const taskLower = taskDescription.toLowerCase();
  for (const [name, skill] of skills) {
    const descLower = skill.metadata.description.toLowerCase();
    const keywords = descLower.split(/\s+/).filter((w) => w.length > 4);
    const taskWords = taskLower.split(/\s+/);
    const matches = keywords.filter((k) => taskWords.some((w) => w.includes(k) || k.includes(w)));
    const tagMatches = skill.metadata.tags?.filter((t) => taskLower.includes(t.toLowerCase())) || [];
    if (matches.length >= 2 || tagMatches.length > 0) {
      relevant.push(name);
    }
  }
  return relevant;
}
