          const fallbackLocation = sqliteAvailable ? ` at ${sqlitePath}` : "";
          console.warn(`[rate-limiter] Redis connection failed after ${maxRetries} attempts (${redisUrl}), falling back to ${fallbackType}${fallbackLocation}`);
