init_dist();
init_zod();
init_schemas3();
class JsonExtractionError extends Error {
  rawInput;
  attemptedStrategies;
  constructor(message, rawInput, attemptedStrategies) {
    super(message);
    this.rawInput = rawInput;
    this.attemptedStrategies = attemptedStrategies;
    this.name = "JsonExtractionError";
  }
}
function formatZodErrors(error45) {
  return error45.issues.map((issue2) => {
    const path2 = issue2.path.length > 0 ? `${issue2.path.join(".")}: ` : "";
    return `${path2}${issue2.message}`;
  });
}
var SCHEMA_REGISTRY = {
  evaluation: EvaluationSchema,
  task_decomposition: TaskDecompositionSchema,
  cell_tree: CellTreeSchema
};
function getSchemaByName(name) {
  const schema = SCHEMA_REGISTRY[name];
  if (!schema) {
    throw new Error(`Unknown schema: ${name}. Available: ${Object.keys(SCHEMA_REGISTRY).join(", ")}`);
  }
  return schema;
}
function extractJsonFromText(text) {
  const trimmed = text.trim();
  const strategies = [];
  strategies.push("direct_parse");
  try {
    return [JSON.parse(trimmed), "direct_parse"];
  } catch {}
  strategies.push("json_code_block");
  const jsonBlockMatch = trimmed.match(/```json\s*([\s\S]*?)```/i);
  if (jsonBlockMatch) {
    try {
      return [JSON.parse(jsonBlockMatch[1].trim()), "json_code_block"];
    } catch {}
  }
  strategies.push("any_code_block");
  const codeBlockMatch = trimmed.match(/```\s*([\s\S]*?)```/);
  if (codeBlockMatch) {
    try {
      return [JSON.parse(codeBlockMatch[1].trim()), "any_code_block"];
    } catch {}
  }
  strategies.push("brace_match_object");
  const objectJson = findBalancedBraces(trimmed, "{", "}");
  if (objectJson) {
    try {
      return [JSON.parse(objectJson), "brace_match_object"];
    } catch {}
  }
  strategies.push("brace_match_array");
  const arrayJson = findBalancedBraces(trimmed, "[", "]");
  if (arrayJson) {
    try {
      return [JSON.parse(arrayJson), "brace_match_array"];
    } catch {}
  }
  strategies.push("repair_json");
  const repaired = attemptJsonRepair(trimmed);
  if (repaired !== trimmed) {
    try {
      return [JSON.parse(repaired), "repair_json"];
    } catch {}
  }
  throw new JsonExtractionError("Could not extract valid JSON from response", text, strategies);
}
var MAX_BRACE_DEPTH = 100;
function findBalancedBraces(text, open, close) {
  const startIdx = text.indexOf(open);
  if (startIdx === -1)
    return null;
  let depth = 0;
  let inString = false;
  let escapeNext = false;
  for (let i = startIdx;i < text.length; i++) {
    const char = text[i];
    if (escapeNext) {
      escapeNext = false;
      continue;
    }
    if (char === "\\") {
      escapeNext = true;
      continue;
    }
    if (char === '"') {
      inString = !inString;
      continue;
    }
    if (inString)
      continue;
    if (char === open) {
      depth++;
      if (depth > MAX_BRACE_DEPTH) {
        return null;
      }
    } else if (char === close) {
      depth--;
      if (depth < 0) {
        return null;
      }
      if (depth === 0) {
        return text.slice(startIdx, i + 1);
      }
    }
  }
  return null;
}
function attemptJsonRepair(text) {
  let repaired = text;
  const match = repaired.match(/[\[{][\s\S]*[\]}]/);
  if (!match)
    return text;
  repaired = match[0];
  repaired = repaired.replace(/(?<![\\])'([^']*)'(?=\s*:)/g, '"$1"');
  repaired = repaired.replace(/,(\s*[}\]])/g, "$1");
  repaired = repaired.replace(/"([^"]*)\n([^"]*)"/g, (_, before, after) => `"${before}\\n${after}"`);
  return repaired;
}
var RAW_INPUT_PREVIEW_LENGTH = 200;
var structured_extract_json = tool({
  description: "Extract JSON from markdown/text response. Tries multiple strategies: direct parse, code blocks, brace matching, JSON repair.",
  args: {
    text: tool.schema.string().describe("Text containing JSON to extract")
  },
  async execute(args, ctx) {
    try {
      const [parsed, method] = extractJsonFromText(args.text);
      return JSON.stringify({
        success: true,
        data: parsed,
        extraction_method: method
      }, null, 2);
    } catch (error45) {
      if (error45 instanceof JsonExtractionError) {
        return JSON.stringify({
          success: false,
          error: error45.message,
          attempted_strategies: error45.attemptedStrategies,
          raw_input_preview: args.text.slice(0, RAW_INPUT_PREVIEW_LENGTH)
        }, null, 2);
      }
      throw error45;
    }
  }
});
var structured_validate = tool({
  description: "Validate agent response against a schema. Extracts JSON and validates with Zod. Returns structured errors for retry feedback.",
  args: {
    response: tool.schema.string().describe("Agent response to validate"),
    schema_name: tool.schema.enum(["evaluation", "task_decomposition", "cell_tree"]).describe("Schema to validate against: " + "evaluation = agent self-eval with criteria, " + "task_decomposition = swarm task breakdown, " + "cell_tree = epic with subtasks"),
    max_retries: tool.schema.number().min(1).max(5).optional().describe("Max retries (for tracking - actual retry logic is external)")
  },
  async execute(args, ctx) {
    const maxRetries = args.max_retries ?? 3;
    const result = {
      success: false,
      attempts: 1,
      errors: []
    };
    if (!args.response || args.response.trim().length === 0) {
      return JSON.stringify({
        valid: false,
        error: "Response is empty or contains only whitespace",
        raw_input: "(empty)"
      });
    }
    let extracted;
    let extractionMethod;
    try {
      [extracted, extractionMethod] = extractJsonFromText(args.response);
      result.extractionMethod = extractionMethod;
    } catch (error45) {
      if (error45 instanceof JsonExtractionError) {
        result.errors = [
          `JSON extraction failed after trying: ${error45.attemptedStrategies.join(", ")}`,
          `Input preview: ${args.response.slice(0, RAW_INPUT_PREVIEW_LENGTH)}...`
        ];
        return JSON.stringify(result, null, 2);
      }
      throw error45;
    }
    try {
      const schema = getSchemaByName(args.schema_name);
      const validated = schema.parse(extracted);
      result.success = true;
      result.data = validated;
      delete result.errors;
      return JSON.stringify(result, null, 2);
    } catch (error45) {
      if (error45 instanceof exports_external.ZodError) {
        const formatted = formatZodErrors(error45);
        result.errors = formatted;
        if (result.attempts < maxRetries) {
          result.errors.push(`
Fix these issues and try again (attempt ${result.attempts}/${maxRetries})`);
        }
        return JSON.stringify(result, null, 2);
      }
      throw error45;
    }
  }
});
