// src/swarm-orchestrate.ts
function generateWorkerHandoff(params) {
  const handoff = {
    contract: {
      task_id: params.task_id,
      files_owned: params.files_owned,
      files_readonly: params.files_readonly || [],
      dependencies_completed: params.dependencies_completed || [],
      success_criteria: params.success_criteria || [
        "All files compile without errors",
        "Tests pass for modified code",
        "Code follows project patterns"
      ]
    },
    context: {
      epic_summary: params.epic_summary,
      your_role: params.your_role,
      what_others_did: params.what_others_did || "",
      what_comes_next: params.what_comes_next || ""
    },
    escalation: {
      blocked_contact: "coordinator",
      scope_change_protocol: "Send swarmmail_send(to=['coordinator'], subject='Scope change request: <task_id>', importance='high') and wait for approval before expanding beyond files_owned"
    }
  };
  return WorkerHandoffSchema.parse(handoff);
}
function validateContract(files_touched, files_owned) {
  if (files_touched.length === 0) {
    return { valid: true, violations: [] };
  }
  const violations = [];
  for (const touchedFile of files_touched) {
    let matched = false;
    for (const ownedPattern of files_owned) {
      if (ownedPattern.includes("*") || ownedPattern.includes("?")) {
        if (minimatch(touchedFile, ownedPattern)) {
          matched = true;
          break;
        }
      } else {
        if (touchedFile === ownedPattern) {
          matched = true;
          break;
        }
      }
    }
    if (!matched) {
      violations.push(touchedFile);
    }
  }
  return {
    valid: violations.length === 0,
    violations
  };
}
async function getSubtaskFilesOwned(projectKey, epicId, subtaskId) {
  try {
    const { readEvents } = await import("swarm-mail");
    const events = await readEvents({
      projectKey,
      types: ["decomposition_generated"]
    }, projectKey);
    const decompositionEvent = events.find((e) => e.type === "decomposition_generated" && e.epic_id === epicId);
    if (!decompositionEvent) {
      console.warn(`[swarm_complete] No decomposition event found for epic ${epicId}`);
      return null;
    }
    const subtaskMatch = subtaskId.match(/\.(\d+)$/);
    if (!subtaskMatch) {
      console.warn(`[swarm_complete] Could not parse subtask index from ${subtaskId}`);
      return null;
    }
    const subtaskIndex = parseInt(subtaskMatch[1], 10);
    const subtasks = decompositionEvent.subtasks || [];
    if (subtaskIndex >= subtasks.length) {
      console.warn(`[swarm_complete] Subtask index ${subtaskIndex} out of range (${subtasks.length} subtasks)`);
      return null;
    }
    const subtask = subtasks[subtaskIndex];
    return subtask.files || [];
  } catch (error45) {
    console.error(`[swarm_complete] Failed to query subtask files:`, error45);
    return null;
  }
}
async function queryEpicSubtasks(projectKey, epicId) {
  try {
    const adapter = await getHiveAdapter(projectKey);
    const cells = await adapter.queryCells(projectKey, { parent_id: epicId });
    return cells.filter((cell) => cell.status !== "tombstone").map((cell) => ({
      id: cell.id,
      title: cell.title,
      description: cell.description || "",
      status: cell.status,
      priority: cell.priority,
      issue_type: cell.type,
      created_at: new Date(cell.created_at).toISOString(),
      updated_at: cell.updated_at ? new Date(cell.updated_at).toISOString() : undefined,
      dependencies: [],
      metadata: {}
    }));
  } catch (error45) {
    console.error(`[swarm] ERROR: Failed to query subtasks for epic ${epicId}:`, error45 instanceof Error ? error45.message : String(error45));
    return [];
  }
}
async function querySwarmMessages(projectKey, threadId) {
  const agentMailAvailable2 = await isToolAvailable("agent-mail");
  if (!agentMailAvailable2) {
    return 0;
  }
  try {
    const inbox = await getSwarmInbox2({
      projectPath: projectKey,
      agentName: "coordinator",
      limit: 5,
      includeBodies: false
    });
    const threadMessages = inbox.messages.filter((m) => m.thread_id === threadId);
    return threadMessages.length;
  } catch (error45) {
    console.warn(`[swarm] Failed to query swarm messages for thread ${threadId}:`, error45);
    return 0;
  }
}
function formatProgressMessage(progress) {
  const lines = [
    `**Status**: ${progress.status}`,
    progress.progress_percent !== undefined ? `**Progress**: ${progress.progress_percent}%` : null,
    progress.message ? `**Message**: ${progress.message}` : null,
    progress.files_touched && progress.files_touched.length > 0 ? `**Files touched**:
${progress.files_touched.map((f) => `- \`${f}\``).join(`
`)}` : null,
    progress.blockers && progress.blockers.length > 0 ? `**Blockers**:
${progress.blockers.map((b) => `- ${b}`).join(`
`)}` : null
  ];
  return lines.filter(Boolean).join(`

`);
}
function classifyFailure(error45) {
  const msg = (typeof error45 === "string" ? error45 : error45.message).toLowerCase();
  if (msg.includes("timeout"))
    return "timeout";
  if (msg.includes("conflict") || msg.includes("reservation"))
    return "conflict";
  if (msg.includes("validation") || msg.includes("schema"))
    return "validation";
  if (msg.includes("context") || msg.includes("token"))
    return "context_overflow";
  if (msg.includes("blocked") || msg.includes("dependency"))
    return "dependency_blocked";
  if (msg.includes("cancel"))
    return "user_cancelled";
  if (msg.includes("tool") || msg.includes("command") || msg.includes("failed to execute")) {
    return "tool_failure";
  }
  return "unknown";
}
