var globalStrikeStorage = new InMemoryStrikeStorage;
var swarm_init = tool({
  description: "Initialize swarm session: discovers available skills, checks tool availability. ALWAYS call at swarm start.",
  args: {
    project_path: tool.schema.string().optional().describe("Project path (for Agent Mail init)"),
    isolation: tool.schema.enum(["worktree", "reservation"]).optional().default("reservation").describe("Isolation mode: 'worktree' for git worktree isolation (requires clean git state), 'reservation' for file reservations (default)")
  },
  async execute(args) {
    const availability = await checkAllTools();
    const report = formatToolAvailability(availability);
    const beadsAvailable = availability.get("beads")?.status.available ?? false;
    const agentMailAvailable2 = availability.get("agent-mail")?.status.available ?? false;
    const warnings = [];
    const degradedFeatures = [];
    if (!beadsAvailable) {
      warnings.push("⚠️  beads (bd) not available - issue tracking disabled, swarm coordination will be limited");
      degradedFeatures.push("issue tracking", "progress persistence");
    }
    if (!agentMailAvailable2) {
      warnings.push("⚠️  agent-mail not available - multi-agent communication disabled");
      degradedFeatures.push("agent communication", "file reservations");
    }
    if (!availability.get("cass")?.status.available) {
      degradedFeatures.push("historical context from past sessions");
    }
    if (!availability.get("hivemind")?.status.available) {
      degradedFeatures.push("persistent learning (using in-memory fallback)");
    }
    const availableSkills = await listSkills();
    const skillsInfo = {
      count: availableSkills.length,
      available: availableSkills.length > 0,
      skills: availableSkills.map((s) => ({
        name: s.name,
        description: s.description,
        hasScripts: s.hasScripts
      }))
    };
    let skillsGuidance;
    if (availableSkills.length > 0) {
      skillsGuidance = `Found ${availableSkills.length} skill(s). Use skills_list to see details, skills_use to activate.`;
    } else {
      skillsGuidance = "No skills found. Add skills to .opencode/skills/ or .claude/skills/ for specialized guidance.";
    }
    const isolationMode = args.isolation ?? "reservation";
    let isolationInfo = {
      mode: isolationMode,
      available: true
    };
    if (isolationMode === "worktree" && args.project_path) {
      const worktreeCheck = await canUseWorktreeIsolation(args.project_path);
      if (worktreeCheck.canUse) {
        const startCommit = await getStartCommit(args.project_path);
        isolationInfo = {
          mode: "worktree",
          available: true,
          start_commit: startCommit ?? undefined
        };
      } else {
        isolationInfo = {
          mode: "reservation",
          available: false,
          reason: `Worktree mode unavailable: ${worktreeCheck.reason}. Falling back to reservation mode.`
        };
        warnings.push(`⚠️  Worktree isolation unavailable: ${worktreeCheck.reason}. Using file reservations instead.`);
      }
    } else if (isolationMode === "worktree" && !args.project_path) {
      isolationInfo = {
        mode: "reservation",
        available: false,
        reason: "Worktree mode requires project_path. Falling back to reservation mode."
      };
      warnings.push("⚠️  Worktree isolation requires project_path. Using file reservations instead.");
    }
    return JSON.stringify({
      ready: true,
      isolation: isolationInfo,
      tool_availability: Object.fromEntries(Array.from(availability.entries()).map(([k, v]) => [
        k,
        {
          available: v.status.available,
          fallback: v.status.available ? null : v.fallbackBehavior
        }
      ])),
      skills: skillsInfo,
      warnings: warnings.length > 0 ? warnings : undefined,
      degraded_features: degradedFeatures.length > 0 ? degradedFeatures : undefined,
      recommendations: {
        skills: skillsGuidance,
        beads: beadsAvailable ? "✓ Use beads for all task tracking" : "Install beads: npm i -g @joelhooks/beads",
        agent_mail: agentMailAvailable2 ? "✓ Use Agent Mail for coordination" : "Start Agent Mail: agent-mail serve",
        isolation: isolationInfo.mode === "worktree" ? "✓ Using git worktree isolation" : "✓ Using file reservation isolation"
      },
      report
    }, null, 2);
  }
});
var swarm_status = tool({
  description: "Get status of a swarm by epic ID",
  args: {
    epic_id: tool.schema.string().describe("Epic bead ID (e.g., bd-abc123)"),
    project_key: tool.schema.string().describe("Project path (for Agent Mail queries)")
  },
  async execute(args) {
    const subtasks = await queryEpicSubtasks(args.project_key, args.epic_id);
    const statusCounts = {
      running: 0,
      completed: 0,
      failed: 0,
      blocked: 0
    };
    const agents = [];
    for (const bead of subtasks) {
      let agentStatus = "pending";
      switch (bead.status) {
        case "in_progress":
          agentStatus = "running";
          statusCounts.running++;
          break;
        case "closed":
          agentStatus = "completed";
          statusCounts.completed++;
          break;
        case "blocked":
          agentStatus = "pending";
          statusCounts.blocked++;
          break;
        default:
          break;
      }
      agents.push({
        bead_id: bead.id,
        agent_name: "",
        status: agentStatus,
        files: []
      });
    }
    const messageCount = await querySwarmMessages(args.project_key, args.epic_id);
    const status = {
      epic_id: args.epic_id,
      total_agents: subtasks.length,
      running: statusCounts.running,
      completed: statusCounts.completed,
      failed: statusCounts.failed,
      blocked: statusCounts.blocked,
      agents,
      last_update: new Date().toISOString()
    };
    const validated = SwarmStatusSchema.parse(status);
    return JSON.stringify({
      ...validated,
      message_count: messageCount,
      progress_percent: subtasks.length > 0 ? Math.round(statusCounts.completed / subtasks.length * 100) : 0
    }, null, 2);
  }
});
var swarm_progress = tool({
  description: "Report progress on a subtask to coordinator. REQUIRED: project_key, agent_name, bead_id, status. Call periodically (every 25% or when blocked) to keep coordinator informed. Use status='blocked' with message explaining the blocker if you're stuck.",
  args: {
    project_key: tool.schema.string().describe("Project path (e.g., '/Users/name/project')"),
    agent_name: tool.schema.string().describe("Your agent name from swarmmail_init"),
    bead_id: tool.schema.string().describe("Task ID from your spawn prompt or hive cell"),
    status: tool.schema.enum(["in_progress", "blocked", "completed", "failed"]).describe("Current status"),
    message: tool.schema.string().optional().describe("Progress message or blockers"),
    progress_percent: tool.schema.number().min(0).max(100).optional().describe("Completion percentage"),
    files_touched: tool.schema.array(tool.schema.string()).optional().describe("Files modified so far")
  },
  async execute(args) {
    const missing = [];
    if (!args.bead_id)
      missing.push("bead_id");
    if (!args.project_key)
      missing.push("project_key");
    if (!args.agent_name)
      missing.push("agent_name");
    if (!args.status)
      missing.push("status");
    if (missing.length > 0) {
      return JSON.stringify({
        success: false,
        error: `Missing required parameters: ${missing.join(", ")}`,
        hint: "swarm_progress reports task progress to the coordinator.",
        example: {
          project_key: "/path/to/project",
          agent_name: "your-agent-name",
          bead_id: "your-task-id from spawn",
          status: "in_progress",
          progress_percent: 50,
          message: "Completed X, working on Y"
        }
      }, null, 2);
    }
    const progress = {
      bead_id: args.bead_id,
      agent_name: args.agent_name,
      status: args.status,
      progress_percent: args.progress_percent,
      message: args.message,
      files_touched: args.files_touched,
      timestamp: new Date().toISOString()
    };
    const validated = AgentProgressSchema.parse(progress);
    if (args.status === "blocked" || args.status === "in_progress") {
      try {
        const adapter = await getHiveAdapter(args.project_key);
        const newStatus = args.status === "blocked" ? "blocked" : "in_progress";
        await adapter.changeCellStatus(args.project_key, args.bead_id, newStatus);
      } catch (error45) {
        console.error(`[swarm] Failed to update cell status: ${error45 instanceof Error ? error45.message : String(error45)}`);
      }
    }
    const epicId = args.bead_id.includes(".") ? args.bead_id.split(".")[0] : args.bead_id;
    await sendSwarmMessage3({
      projectPath: args.project_key,
      fromAgent: args.agent_name,
      toAgents: [],
      subject: `Progress: ${args.bead_id} - ${args.status}`,
      body: formatProgressMessage(validated),
      threadId: epicId,
      importance: args.status === "blocked" ? "high" : "normal"
    });
    let checkpointCreated = false;
    if (args.progress_percent !== undefined && args.files_touched && args.files_touched.length > 0) {
      const milestones = [25, 50, 75];
      if (milestones.includes(args.progress_percent)) {
        try {
          const checkpoint = {
            epic_id: epicId,
            bead_id: args.bead_id,
            strategy: "file-based",
            files: args.files_touched,
            dependencies: [],
            directives: {},
            recovery: {
              last_checkpoint: Date.now(),
              files_modified: args.files_touched,
              progress_percent: args.progress_percent,
              last_message: args.message
            }
          };
          const checkpointData = JSON.stringify(checkpoint);
          const checkpointEvent = createEvent4("swarm_checkpointed", {
            project_key: args.project_key,
            ...checkpoint,
            checkpoint_size_bytes: Buffer.byteLength(checkpointData, "utf8"),
            trigger: "progress"
          });
          await appendEvent3(checkpointEvent, args.project_key);
          const checkpointId = `ckpt-${Date.now()}-${args.bead_id}`;
          const createdEvent = createEvent4("checkpoint_created", {
            project_key: args.project_key,
            epic_id: epicId,
            bead_id: args.bead_id,
            agent_name: args.agent_name,
            checkpoint_id: checkpointId,
            trigger: "progress",
            progress_percent: args.progress_percent,
            files_snapshot: args.files_touched
          });
          await appendEvent3(createdEvent, args.project_key);
          checkpointCreated = true;
        } catch (error45) {
          console.warn(`[swarm_progress] Auto-checkpoint failed at ${args.progress_percent}%:`, error45);
        }
      }
    }
    return `Progress reported: ${args.status}${args.progress_percent !== undefined ? ` (${args.progress_percent}%)` : ""}${checkpointCreated ? " [checkpoint created]" : ""}`;
  }
});
